from pathlib import Path
import sys
code_dir=Path('/kaggle/working/accuracy_code');code_dir.mkdir(exist_ok=True)
sources={'accuracy_selection.py': '"""Accuracy-oriented exploratory selection using development predictions only."""\nimport numpy as np\nfrom sklearn.model_selection import StratifiedGroupKFold\nfrom sklearn.metrics import roc_auc_score\n\nARCHITECTURES = [\'efficientnet_b0\', \'densenet121\', \'resnet18\']\nSEEDS = [42, 123, 2026]\n\n\ndef member_name(size, architecture, seed):\n    return f\'{size}/{architecture}_seed_{seed}\'\n\n\ndef candidates():\n    result = {}\n    for size in [224, 320]:\n        for architecture in ARCHITECTURES:\n            result[f\'{size}_{architecture}\'] = [member_name(size, architecture, s) for s in SEEDS]\n        result[f\'{size}_all_architectures\'] = [member_name(size, a, s) for a in ARCHITECTURES for s in SEEDS]\n    for architecture in ARCHITECTURES:\n        result[f\'both_{architecture}\'] = [member_name(z, architecture, s) for z in [224, 320] for s in SEEDS]\n    result[\'both_all_architectures\'] = [member_name(z, a, s) for z in [224, 320] for a in ARCHITECTURES for s in SEEDS]\n    return result\n\n\ndef validate_scores(y, p):\n    y, p = np.asarray(y), np.asarray(p, dtype=float)\n    if y.ndim != 1 or p.shape != y.shape or set(y) != {0, 1}:\n        raise ValueError(\'Both binary classes and aligned one-dimensional scores required\')\n    if not np.isfinite(p).all() or not ((p >= 0) & (p <= 1)).all():\n        raise ValueError(\'Scores must be finite and in [0,1]\')\n    return y, p\n\n\ndef accuracy_threshold(y, p):\n    y, p = validate_scores(y, p)\n    values = np.unique(p)\n    # Midpoints avoid using an observed score as the decision boundary.\n    thresholds = np.r_[0., values[:-1] + np.diff(values) / 2, np.nextafter(values[-1], np.inf)]\n    correct = np.array([np.sum((p >= t) == y) for t in thresholds])\n    # Sorted thresholds: ties choose the lowest, preserving greater sensitivity.\n    index = int(np.argmax(correct))\n    return float(thresholds[index]), int(correct[index])\n\n\ndef choose(y, groups, scores):\n    y, groups = np.asarray(y), np.asarray(groups)\n    if groups.shape != y.shape or any(str(g) in {\'\', \'nan\', \'None\'} for g in groups):\n        raise ValueError(\'Aligned nonmissing groups required\')\n    definitions = candidates()\n    required = set(definitions[\'both_all_architectures\'])\n    if set(scores) != required:\n        raise ValueError(\'Exactly 18 original member selection scores required\')\n    for p in scores.values():\n        validate_scores(y, p)\n    folds = list(StratifiedGroupKFold(n_splits=5, shuffle=True, random_state=20261026).split(np.zeros(len(y)), y, groups))\n    fold_ids = np.full(len(y), -1, dtype=int)\n    for fold, (train, valid) in enumerate(folds):\n        if set(groups[train]) & set(groups[valid]):\n            raise ValueError(\'Group overlap within threshold cross-validation\')\n        if set(y[train]) != {0, 1} or set(y[valid]) != {0, 1}:\n            raise ValueError(\'Both classes required in each fold\')\n        fold_ids[valid] = fold\n    records = []\n    for name, members in definitions.items():\n        p = np.mean([scores[m] for m in members], axis=0)\n        oof = np.empty(len(y), dtype=int)\n        thresholds = []\n        for train, valid in folds:\n            t, _ = accuracy_threshold(y[train], p[train])\n            oof[valid] = p[valid] >= t\n            thresholds.append(t)\n        records.append(dict(candidate=name, members=members, member_count=len(members),\n                            correct=int(np.sum(oof == y)), images=len(y),\n                            oof_accuracy=float(np.mean(oof == y)),\n                            selection_auroc=float(roc_auc_score(y, p)),\n                            fold_thresholds=thresholds))\n    # Preserve the original model on an accuracy tie, then prefer fewer members and fixed name order.\n    records.sort(key=lambda r: (-r[\'correct\'], r[\'candidate\'] != \'320_efficientnet_b0\', r[\'member_count\'], r[\'candidate\']))\n    return dict(selected=records[0], candidates=records, fold_ids=fold_ids.tolist(),\n                criterion=\'Pooled five-fold grouped out-of-fold threshold accuracy on selection only\',\n                tie_rule=\'Original 320 EfficientNet-B0 candidate, then fewer members, then name\',\n                test_predictions_accessed=False,\n                limitation=\'Threshold cross-fitting only: original checkpoint selection used this selection cohort. This is not unbiased nested validation of training or candidate selection.\')\n', 'predict_accuracy.py': '"""Inference for an accuracy-selected mixed-architecture research ensemble."""\nimport argparse\nimport hashlib\nimport json\nfrom pathlib import Path\n\n\ndef model_for(architecture):\n    import torch\n    from torchvision import models\n    if architecture == \'efficientnet_b0\':\n        m = models.efficientnet_b0(weights=None)\n        m.classifier[1] = torch.nn.Linear(m.classifier[1].in_features, 1)\n    elif architecture == \'densenet121\':\n        m = models.densenet121(weights=None)\n        m.classifier = torch.nn.Linear(m.classifier.in_features, 1)\n    elif architecture == \'resnet18\':\n        m = models.resnet18(weights=None)\n        m.fc = torch.nn.Linear(m.fc.in_features, 1)\n    else:\n        raise ValueError(\'Unsupported architecture\')\n    return m\n\n\ndef image_tensor(path, size):\n    from PIL import Image, ImageOps\n    from torchvision import transforms\n    with Image.open(path) as image:\n        image = ImageOps.pad(image.convert(\'RGB\'), (size, size), method=Image.Resampling.BICUBIC, color=0)\n    return transforms.Normalize([.485, .456, .406], [.229, .224, .225])(transforms.ToTensor()(image))\n\n\ndef predict(directory, image, device=\'cpu\'):\n    import torch\n    import math\n    root = Path(directory).resolve()\n    config = json.loads((root/\'accuracy_config.json\').read_text())\n    if config[\'classes\'] != [\'NORMAL\', \'PNEUMONIA\'] or config[\'aggregation\'] != \'mean_raw_sigmoid\':\n        raise ValueError(\'Unsupported output mapping\')\n    threshold = config[\'threshold\']\n    if not math.isfinite(threshold) or not 0 <= threshold <= math.nextafter(1., math.inf):\n        raise ValueError(\'Invalid threshold\')\n    members = config[\'members\']\n    if not members or len({m[\'checkpoint\'] for m in members}) != len(members):\n        raise ValueError(\'Missing or duplicate members\')\n    scores, cache = [], {}\n    torch.set_num_threads(2)\n    with torch.inference_mode():\n        for member in members:\n            path = (root/member[\'checkpoint\']).resolve()\n            if not path.is_relative_to(root) or not path.is_file():\n                raise ValueError(\'Checkpoint path must remain inside model directory\')\n            if hashlib.sha256(path.read_bytes()).hexdigest() != member[\'sha256\']:\n                raise ValueError(\'Checkpoint checksum mismatch\')\n            size = member[\'image_size\']\n            if size not in {224, 320}: raise ValueError(\'Unsupported resolution\')\n            if size not in cache: cache[size] = image_tensor(image, size).unsqueeze(0).to(device)\n            model = model_for(member[\'architecture\'])\n            model.load_state_dict(torch.load(path, map_location=\'cpu\', weights_only=True), strict=True)\n            model.to(device).eval()\n            scores.append(float(torch.sigmoid(model(cache[size]).flatten())[0].cpu()))\n            del model\n    score = sum(scores)/len(scores)\n    return dict(pneumonia_score=score, threshold=threshold, predicted_label=config[\'classes\'][int(score >= threshold)],\n                member_scores=scores, note=\'Uncalibrated research score, not a diagnosis or clinical probability\')\n\n\nif __name__ == \'__main__\':\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--model-dir\',required=True); parser.add_argument(\'--image\',required=True)\n    parser.add_argument(\'--device\',choices=[\'cpu\',\'cuda\'],default=\'cpu\')\n    args=parser.parse_args()\n    print(json.dumps(predict(args.model_dir,args.image,args.device)))\n', 'run_accuracy_experiment.py': '"""Frozen-model accuracy experiment. Never choose a model or cutoff from test outcomes."""\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport shutil\nimport subprocess\nimport sys\nimport time\n\nimport numpy as np\nimport pandas as pd\nimport sklearn\nimport torch\nfrom PIL import Image\nfrom accuracy_selection import choose, accuracy_threshold, candidates\nfrom predict_accuracy import model_for, image_tensor\nfrom compare_experiments import metrics\nfrom analyze_benchmark_comparison import analyze\n\n\ndef save(path, value):\n    Path(path).write_text(json.dumps(value, indent=2), encoding=\'utf-8\')\n\n\ndef aligned_manifest(low, high):\n    fields=[\'sha256\',\'patient\',\'label\',\'split\',\'original_split\',\'filename\']\n    frames=[pd.read_csv(p/\'split_manifest.csv\')[fields].sort_values(\'sha256\').reset_index(drop=True) for p in [low,high]]\n    if not frames[0].equals(frames[1]): raise ValueError(\'Resolution manifests disagree\')\n    frame=frames[0]\n    if frame.isna().any().any() or frame.sha256.duplicated().any(): raise ValueError(\'Invalid manifest identities\')\n    expected={\'train\':3815,\'selection\':456,\'calibration\':482,\'test\':618}\n    if frame.groupby(\'split\').size().to_dict()!=expected: raise ValueError(\'Unexpected cohort sizes\')\n    if frame.groupby(\'patient\').split.nunique().max()!=1: raise ValueError(\'Cross-partition group overlap\')\n    digest=hashlib.sha256(\'\\n\'.join(sorted(frame[frame.split==\'test\'].sha256)).encode()).hexdigest()\n    if digest!=\'c0de6a4a18c8c295d85551b5b8602410e2e26d173b8ab9f141e82cd6fdca9378\':\n        raise ValueError(\'Frozen test cohort changed\')\n    return frame\n\n\ndef member_info(name, roots):\n    size,trial=name.split(\'/\')\n    architecture,seed=trial.rsplit(\'_seed_\',1)\n    return dict(name=name,image_size=int(size),architecture=architecture,seed=int(seed),\n                original_path=roots[int(size)]/trial/\'best_weights.pt\')\n\n\ndef selection_scores(frame, roots):\n    expected=frame[frame.split==\'selection\'].reset_index(drop=True)\n    scores={}\n    for name in candidates()[\'both_all_architectures\']:\n        size,trial=name.split(\'/\')\n        data=pd.read_csv(roots[int(size)]/trial/\'selection_predictions.csv\').sort_values(\'sha256\').reset_index(drop=True)\n        for field in [\'sha256\',\'patient\']:\n            if not data[field].equals(expected[field]): raise ValueError(\'Selection identity mismatch: \'+name)\n        if not np.array_equal(data.y_true,expected.label): raise ValueError(\'Selection labels disagree\')\n        scores[name]=data.probability.to_numpy(float)\n    return expected, scores\n\n\ndef source_path(row, data_root):\n    return data_root/row.original_split/(\'NORMAL\' if row.y_true==0 else \'PNEUMONIA\')/row.filename\n\n\ndef infer(frame, members, data_root, device, output, split):\n    # Decode identity before any inference. Preprocessing is the original full-image letterbox.\n    paths=[]\n    for row in frame.itertuples():\n        path=source_path(row,data_root)\n        with Image.open(path) as image:\n            gray=image.convert(\'L\')\n            digest=hashlib.sha256(str(gray.size).encode()+gray.tobytes()).hexdigest()\n        if digest!=row.sha256: raise ValueError(\'Pixel identity mismatch: \'+row.filename)\n        paths.append(path)\n    result={}\n    for size in sorted({m[\'image_size\'] for m in members}):\n        tensors=[image_tensor(p,size) for p in paths]\n        for member in [m for m in members if m[\'image_size\']==size]:\n            model=model_for(member[\'architecture\'])\n            model.load_state_dict(torch.load(member[\'original_path\'],map_location=\'cpu\',weights_only=True),strict=True)\n            model.to(device).eval(); values=[]\n            with torch.inference_mode():\n                for start in range(0,len(tensors),32):\n                    batch=torch.stack(tensors[start:start+32]).to(device)\n                    values.extend(torch.sigmoid(model(batch).flatten()).cpu().numpy().astype(float))\n            values=np.asarray(values)\n            if len(values)!=len(frame) or not np.isfinite(values).all(): raise ValueError(\'Invalid inference output\')\n            result[member[\'name\']]=values\n            print(\'MEMBER_INFERENCE\',split,member[\'name\'],len(values),flush=True)\n            del model\n        del tensors\n    raw=np.mean([result[m[\'name\']] for m in members],axis=0)\n    member_frame=frame[[\'sha256\',\'patient\',\'y_true\']].copy()\n    for name,values in result.items(): member_frame[name]=values\n    member_frame.to_csv(output/f\'{split}_raw_member_scores.csv\',index=False)\n    return raw\n\n\ndef run(low,high,data_root,output,protocol,locks):\n    start=time.monotonic()\n    low,high,data_root,output=map(Path,[low,high,data_root,output])\n    output.mkdir(parents=True,exist_ok=True)\n    save(output/\'protocol.json\',protocol)\n    torch.set_num_threads(2)\n    torch.manual_seed(20261026)\n    torch.backends.cudnn.benchmark=False\n    torch.backends.cudnn.deterministic=True\n    device=\'cuda\' if torch.cuda.is_available() else \'cpu\'\n    roots={224:low,320:high}\n    frame=aligned_manifest(low,high)\n    # Check all original weights without looking at any test probability file.\n    for name in candidates()[\'both_all_architectures\']:\n        m=member_info(name,roots)\n        digest=hashlib.sha256(m[\'original_path\'].read_bytes()).hexdigest()\n        if digest!=locks[name]: raise ValueError(\'Original checkpoint lock mismatch: \'+name)\n    selected_frame,scores=selection_scores(frame,roots)\n    choice=choose(selected_frame.label,selected_frame.patient,scores)\n    save(output/\'development_choice.json\',choice)\n    selected_frame.assign(threshold_cv_fold=choice[\'fold_ids\']).to_csv(output/\'selection_folds.csv\',index=False)\n    print(\'DEVELOPMENT_CHOICE\',json.dumps(choice),flush=True)\n    members=[member_info(name,roots) for name in choice[\'selected\'][\'members\']]\n    calibration=frame[frame.split==\'calibration\'].rename(columns={\'label\':\'y_true\'}).reset_index(drop=True)\n    raw=infer(calibration,members,data_root,device,output,\'calibration\')\n    threshold,correct=accuracy_threshold(calibration.y_true,raw)\n    config=dict(classes=[\'NORMAL\',\'PNEUMONIA\'],aggregation=\'mean_raw_sigmoid\',threshold=threshold,\n                selected_candidate=choice[\'selected\'][\'candidate\'],members=[],\n                objective=\'Maximum overall accuracy on the separate calibration partition\',\n                threshold_tie_rule=\'Lowest midpoint threshold among maximum-accuracy candidates\',\n                score_interpretation=\'Uncalibrated research score, not a clinical probability\',\n                status=\'Exploratory reuse of previously inspected source cohorts\')\n    for member in members:\n        relative=\'members/\'+member[\'name\'].replace(\'/\',\'_\')+\'/best_weights.pt\'\n        dest=output/relative;dest.parent.mkdir(parents=True,exist_ok=True)\n        shutil.copyfile(member[\'original_path\'],dest)\n        config[\'members\'].append(dict(architecture=member[\'architecture\'],image_size=member[\'image_size\'],\n                                     checkpoint=relative,sha256=locks[member[\'name\']]))\n    # Freeze model, exported weights, and cutoff BEFORE reading old or new test outcomes.\n    save(output/\'accuracy_config.json\',config)\n    frozen_sha=hashlib.sha256((output/\'accuracy_config.json\').read_bytes()).hexdigest()\n    calibration=calibration.assign(probability=raw,prediction=(raw>=threshold).astype(int))\n    calibration.to_csv(output/\'calibration_predictions.csv\',index=False)\n    save(output/\'calibration_fit.json\',dict(images=len(calibration),correct=correct,\n        metrics=metrics(calibration),threshold=threshold,config_sha256=frozen_sha,\n        limitation=\'In-sample cutoff fitting; not an independent estimate of future accuracy\'))\n    print(\'MODEL_FROZEN\',json.dumps(dict(candidate=config[\'selected_candidate\'],threshold=threshold,config_sha256=frozen_sha)),flush=True)\n    test=frame[frame.split==\'test\'].rename(columns={\'label\':\'y_true\'}).reset_index(drop=True)\n    p=infer(test,members,data_root,device,output,\'test\')\n    test=test.assign(probability=p,prediction=(p>=threshold).astype(int))\n    test.to_csv(output/\'test_predictions.csv\',index=False)\n    comparison=analyze(high,output,output/\'paired_uncertainty\',replicates=1000)\n    cli=Path(__file__).with_name(\'predict_accuracy.py\')\n    shutil.copyfile(cli,output/\'predict_accuracy.py\')\n    checks=[]\n    env=dict(os.environ,OMP_NUM_THREADS=\'2\',MKL_NUM_THREADS=\'2\')\n    for row in test.iloc[:2].itertuples():\n        process=subprocess.run([sys.executable,str(cli),\'--model-dir\',str(output),\'--image\',str(source_path(row,data_root)),\'--device\',\'cpu\'],capture_output=True,text=True,timeout=600,env=env)\n        if process.returncode!=0: raise RuntimeError(\'Inference CLI failed: \'+process.stderr[-2000:])\n        answer=json.loads(process.stdout)\n        difference=abs(answer[\'pneumonia_score\']-row.probability)\n        changed=int(answer[\'predicted_label\']!=config[\'classes\'][row.prediction])\n        checks.append(dict(sha256=row.sha256,score_difference=difference,changed_prediction=changed))\n    passed=all(c[\'score_difference\']<=1e-4 and c[\'changed_prediction\']==0 for c in checks)\n    if hashlib.sha256((output/\'accuracy_config.json\').read_bytes()).hexdigest()!=frozen_sha:\n        raise ValueError(\'Configuration changed after freeze\')\n    report=dict(status=\'completed\' if passed else \'CLI numerical verification failed\',\n                selected_candidate=config[\'selected_candidate\'],members=len(members),\n                selection_oof_accuracy=choice[\'selected\'][\'oof_accuracy\'],\n                calibration_accuracy=correct/len(calibration),threshold=threshold,\n                test_metrics=metrics(test),paired_comparison=comparison,\n                cli_verification=dict(passed=passed,images=2,selection=\'First two ascending pixel hashes\',checks=checks,tolerance=1e-4),\n                confusion=dict(tn=int(((test.y_true==0)&(test.prediction==0)).sum()),\n                               fp=int(((test.y_true==0)&(test.prediction==1)).sum()),\n                               fn=int(((test.y_true==1)&(test.prediction==0)).sum()),\n                               tp=int(((test.y_true==1)&(test.prediction==1)).sum())),\n                environment=dict(device=device,python=sys.version,torch=torch.__version__,numpy=np.__version__,\n                                 pandas=pd.__version__,sklearn=sklearn.__version__,\n                                 gpu=torch.cuda.get_device_name(0) if device==\'cuda\' else None),\n                runtime_seconds=time.monotonic()-start,\n                config_sha256=frozen_sha,training_performed=False,\n                limitations=protocol[\'limitations\'])\n    save(output/\'summary.json\',report)\n    print(\'ACCURACY_EXPERIMENT_DONE\',json.dumps(report),flush=True)\n    if not passed: raise RuntimeError(\'CLI check failed; frozen results retained\')\n    return report\n', 'compare_experiments.py': '"""Paired descriptive comparison of frozen predictions; never fits thresholds."""\nimport argparse\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.metrics import roc_auc_score, average_precision_score\n\n\ndef metrics(frame):\n    y = frame.y_true.to_numpy(dtype=int)\n    p = frame.probability.to_numpy(dtype=float)\n    pred = frame.prediction.to_numpy(dtype=int)\n    return {\n        \'auroc\': float(roc_auc_score(y, p)),\n        \'average_precision\': float(average_precision_score(y, p)),\n        \'accuracy\': float(np.mean(y == pred)),\n        \'sensitivity\': float(np.mean(pred[y == 1] == 1)),\n        \'specificity\': float(np.mean(pred[y == 0] == 0)),\n        \'brier_score\': float(np.mean((y - p) ** 2)),\n    }\n\n\ndef compare(baseline_dir, followup_dir, replicates=1000):\n    if replicates < 1:\n        raise ValueError(\'replicates must be positive\')\n    frames = []\n    for directory in (baseline_dir, followup_dir):\n        frame = pd.read_csv(Path(directory) / \'test_predictions.csv\')\n        required = {\'sha256\', \'patient\', \'y_true\', \'probability\', \'prediction\'}\n        if not required.issubset(frame.columns) or frame.sha256.duplicated().any():\n            raise ValueError(\'Missing fields or duplicate image hashes\')\n        if set(frame.y_true) != {0, 1} or not set(frame.prediction).issubset({0, 1}):\n            raise ValueError(\'Expected binary labels with both classes represented\')\n        if not np.isfinite(frame.probability).all() or not frame.probability.between(0, 1).all():\n            raise ValueError(\'Invalid probabilities\')\n        if frame.patient.isna().any() or frame.sha256.isna().any():\n            raise ValueError(\'Missing pairing or cluster identifiers\')\n        frames.append(frame.sort_values(\'sha256\').reset_index(drop=True))\n    a, b = frames\n    for column in (\'sha256\', \'patient\', \'y_true\'):\n        if not a[column].equals(b[column]):\n            raise ValueError(\'Test cohorts or labels differ: \' + column)\n    ma, mb = metrics(a), metrics(b)\n    groups = [np.flatnonzero(a.patient.to_numpy() == group) for group in a.patient.unique()]\n    rng = np.random.default_rng(42)\n    differences = []\n    for _ in range(replicates):\n        idx = np.concatenate([groups[i] for i in rng.integers(0, len(groups), len(groups))])\n        if a.iloc[idx].y_true.nunique() != 2:\n            continue\n        sa, sb = metrics(a.iloc[idx]), metrics(b.iloc[idx])\n        differences.append({key: sb[key] - sa[key] for key in sa})\n    if not differences:\n        raise ValueError(\'No bootstrap sample contained both classes\')\n    return {\n        \'status\': \'Exploratory paired comparison; original test results already inspected\',\n        \'direction\': \'followup minus baseline; lower is better for Brier score only\',\n        \'images\': len(a), \'filename_proxy_groups\': len(groups),\n        \'baseline\': ma, \'followup\': mb,\n        \'difference\': {key: mb[key] - ma[key] for key in ma},\n        \'paired_cluster_bootstrap_95ci\': {\n            key: np.percentile([d[key] for d in differences], [2.5, 97.5]).tolist()\n            for key in ma},\n        \'bootstrap_replicates\': len(differences),\n        \'limitations\': \'Filename groups are proxies. Intervals describe test sampling, not training variation, model selection uncertainty or external generalization. No multiplicity adjustment. Thresholds remain those saved by each experiment.\'\n    }\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'baseline\', type=Path)\n    parser.add_argument(\'followup\', type=Path)\n    parser.add_argument(\'--output\', type=Path, required=True)\n    parser.add_argument(\'--replicates\', type=int, default=1000)\n    args = parser.parse_args()\n    report = compare(args.baseline, args.followup, args.replicates)\n    args.output.parent.mkdir(parents=True, exist_ok=True)\n    args.output.write_text(json.dumps(report, indent=2))\n    print(json.dumps(report, indent=2))\n', 'analyze_benchmark_comparison.py': '"""Descriptive paired uncertainty for already-frozen source test predictions."""\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nfrom compare_experiments import compare, metrics\n\n\ndef analyze(previous, benchmark, output, replicates=1000):\n    output=Path(output);output.mkdir(parents=True,exist_ok=True)\n    comparison=compare(previous,benchmark,replicates)\n    frame=pd.read_csv(Path(benchmark)/\'test_predictions.csv\').sort_values(\'sha256\').reset_index(drop=True)\n    groups=[np.flatnonzero(frame.patient.to_numpy()==g) for g in frame.patient.unique()]\n    rng=np.random.default_rng(42); samples=[]\n    for _ in range(replicates):\n        indices=np.concatenate([groups[i] for i in rng.integers(0,len(groups),len(groups))])\n        sample=frame.iloc[indices]\n        if sample.y_true.nunique()==2: samples.append(metrics(sample))\n    if not samples: raise ValueError(\'No usable bootstrap samples\')\n    intervals={name:np.percentile([m[name] for m in samples],[2.5,97.5]).tolist() for name in samples[0]}\n    report={\'status\':\'Exploratory; the original source test was previously inspected\',\n            \'benchmark_metrics\':metrics(frame),\'benchmark_cluster_bootstrap_95ci\':intervals,\n            \'bootstrap_replicates\':len(samples),\'paired_comparison\':comparison,\n            \'interpretation\':\'Conditional test-sampling uncertainty only. Does not capture training, model selection, proxy-group error or external generalization. No threshold refitting or model selection occurs.\'}\n    (output/\'comparison.json\').write_text(json.dumps(report,indent=2))\n    print(\'COMPARISON_DONE\',json.dumps(report),flush=True)\n    return report\n\n\nif __name__==\'__main__\':\n    import argparse\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'previous\',type=Path);parser.add_argument(\'benchmark\',type=Path)\n    parser.add_argument(\'--output\',type=Path,required=True)\n    args=parser.parse_args();analyze(args.previous,args.benchmark,args.output)\n'}
